#
# Прогон суит одного шарда e2e-newman и ЧТЕНИЕ его исхода как данных.
#
# ПОЧЕМУ ЭТО ФАЙЛ, А НЕ БЛОК `run:` В WORKFLOW
#
# Провайдер исполняет тело `run:` через `bash --noprofile --norc -eo pipefail`.
# Под `-e` команда, чей отказ не стоит в условии, обрывает оболочку НЕМЕДЛЕННО:
# до присваивания `rc=$?`, до `case`, до аннотации. Прежняя форма была ровно
# такой (`./scripts/newman-parallel.sh; rc=$?`), и развилка по коду не
# исполнялась НИ РАЗУ (#2346).
#
# Следствий у этого три, и все три тихие:
#
#   * аннотация «Прогон недействителен» не печаталась никогда — а она
#     единственное место, где «не выполнилось» отличается от красного;
#   * `rc=1` не проглатывался вопреки объявлению в комментарии того же шага:
#     красная суита валила ШАГ ПРОГОНА, а не шаг-гейт, и разбор начинался не с
#     той стороны;
#   * остановка наблюдателя (`touch` файла останова и `wait`) стояла ПОСЛЕ
#     обрывающей команды, то есть тоже не исполнялась.
#
# Тот же класс уже чинили выносом в скрипт у сводного вердикта
# (`pr-verdict-wait.sh`, #1073) — и по той же причине: логику, живущую в YAML,
# не исполняет ни одна проба, поэтому её дефект виден только на живом прогоне.
#
# ТРИ ИСХОДА ПРОГОНЩИКА, И ПУТАТЬ ИХ НЕЛЬЗЯ (словарь — его собственный,
# `deploy/scripts/newman-parallel.sh`, здесь он только ЧИТАЕТСЯ):
#
#   0  суиты исполнились, вердикт вынесен и зелен;
#   1  суиты ИСПОЛНИЛИСЬ, часть красная. Вердикт по ним выносят шаги-гейты ниже,
#      и он обязан остаться за ними: второй вердикт рядом с первым — способ
#      получить два разных ответа на один вопрос. Поэтому код 1 здесь
#      проглатывается СОЗНАТЕЛЬНО, и это не маска: гейты ниже стоят под
#      `if: always()`, они отработают и доложат;
#   2  прогон НЕДЕЙСТВИТЕЛЕН — не встал проброс, упал посев, либо вердиктного
#      гейта не оказалось по адресу. Результата нет ни красного, ни зелёного.
#
# ПОЧЕМУ КОД 2 ВАЛИТ ИМЕННО ЭТОТ ШАГ. Прежде тут стояло `|| true`, глотавшее оба
# кода разом: шаг отчитывался успехом, не исполнив ничего, а красным становился
# ШАГ ЧЕРЕЗ ДВА — гейт суиты, докладывающий «нет отчётов». Разбор после этого
# начинался не с той стороны: упавшее утверждение искали там, где не исполнилось
# ни одного запроса (наблюдалось на четырёх шардах одного прогона). Гейты ниже
# стоят под `if: always()` и от этого не теряются — меняется только то, ГДЕ
# впервые виден незапуск.
#
# ЧЕТВЁРТОГО КОДА У ПРОГОНЩИКА НЕТ, поэтому любой иной — это он сам не дошёл до
# своего вердикта (снят по времени, убит по памяти, сигнал). Это тоже «не
# выполнилось», и молчать о нём нельзя: без ветви `*` такой код прошёл бы мимо
# развилки и выглядел бы обычным красным.
#
# СОБСТВЕННЫЙ СЛОВАРЬ ЭТОГО СКРИПТА — ДВА КОДА, и он уже:
#
#   0  прогон состоялся; вердикт о его СОДЕРЖИМОМ — за шагами-гейтами ниже;
#   2  «не выполнилось» — вердикта нет вовсе, и рядом напечатана аннотация.
#
# Код прогонщика при этом всегда назван словами в выводе, поэтому сведение
# «2 и неизвестный» к одному исходу шага ничего не теряет.
#
# `set -e` здесь НЕ включается сознательно; каждая команда, чей исход что-то
# значит, проверяется явно. Провайдер всё равно исполняет скрипт под `-e`
# (`bash -e <файл>` — флаг с командной строки, `set -uo pipefail` его не
# снимает), поэтому вызов прогонщика стоит в УСЛОВНОМ контексте: `&& rc=0 || rc=$?`.
set -uo pipefail

: "${SERVICES:?SERVICES не задан — наблюдатель читал бы умолчание прогонщика (все суиты дерева) и печатал бы «0 отчётов» по тем, которых этот шард не гоняет}"

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Ручки существуют РАДИ ПРОВЕРЯЕМОСТИ: проба подставляет свои прогонщик и
# наблюдателя и уводит файл останова из общего каталога. Умолчания — боевые и
# дословно те же, что стояли в блоке `run:` до выноса.
: "${NEWMAN_LIVE_STOP_FILE:=/tmp/newman-live.stop}"
: "${NEWMAN_LIVE_INTERVAL:=20}"
: "${SHARD_WATCH_CMD:=}"
: "${SHARD_RUN_CMD:=}"

start_watch() {
  if [ -n "$SHARD_WATCH_CMD" ]; then
    "$SHARD_WATCH_CMD"
  else
    # --services сужает наблюдателя до состава ШАРДА (см. требование SERVICES выше).
    python3 "$here/newman-live.py" watch \
      --services "$SERVICES" \
      --interval "$NEWMAN_LIVE_INTERVAL" \
      --stop-file "$NEWMAN_LIVE_STOP_FILE"
  fi
}

run_suites() {
  if [ -n "$SHARD_RUN_CMD" ]; then
    "$SHARD_RUN_CMD"
  else
    # cwd задан шагом (`working-directory: deploy`).
    ./scripts/newman-parallel.sh
  fi
}

rm -f "$NEWMAN_LIVE_STOP_FILE"

# Наблюдатель пишет таблицу прогресса в ЭТОТ ЖЕ стримящийся лог: прогон, за
# которым нельзя следить, отлаживают следующим прогоном, а цена ошибки в
# фикстуре — полный цикл стенда. Вердикта он не выносит и говорит это первой
# строкой.
start_watch &
live_pid=$!

# КОД ВОЗВРАТА — ДАННЫЕ. Условный контекст переживает `-e` у вызывающего.
run_suites && rc=0 || rc=$?

# Наблюдатель ждёт файл останова в цикле БЕЗ ИНОЙ ГРАНИЦЫ. Если файл не удалось
# создать, `wait` висел бы до предела шага, поэтому здесь второй путь — сигнал.
if ! touch "$NEWMAN_LIVE_STOP_FILE" 2>/dev/null; then
  echo "::warning title=Файл останова не создан::наблюдатель снимается сигналом ($NEWMAN_LIVE_STOP_FILE недоступен для записи)"
  kill "$live_pid" 2>/dev/null || true
fi
wait "$live_pid" || true

case "$rc" in
  0)
    echo "[шард] прогонщик отдал 0 — суиты исполнились; вердикт о содержимом отчётов за шагами-гейтами ниже"
    ;;
  1)
    echo "[шард] прогонщик отдал 1 — суиты ИСПОЛНИЛИСЬ, часть красная."
    echo "[шард] вердикт по ним выносят шаги-гейты ниже (они под always() и отработают): второй вердикт рядом с первым дал бы два разных ответа на один вопрос."
    ;;
  2)
    echo "::error title=Прогон недействителен::rc=2 — результата нет, ни красного, ни зелёного: суиты не запускались ЛИБО вердиктного гейта не оказалось по адресу. Какая из причин — названо выше, в выводе newman-parallel.sh."
    exit 2
    ;;
  *)
    echo "::error title=Прогон недействителен::прогонщик вышел кодом $rc, которого нет в его словаре (0/1/2) — значит он не дошёл до собственного вердикта (снят по времени, убит по памяти, сигнал). Результата нет, и это НЕ красное."
    exit 2
    ;;
esac
